# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("layernorm_forward", &layernorm_forward, "Fused LayerNorm forward");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void layernorm_kernel(const float* __restrict__ x, const float* __restrict__ weight, const float* __restrict__ bias, float* __restrict__ out, int rows, int hidden, float eps) {
    int row = blockIdx.x;
    if (row >= rows) return;

    extern __shared__ float shared[];
    float* s_sum = shared;
    float* s_sum_sq = shared + blockDim.x;

    const float* row_in = x + row * hidden;
    float* row_out = out + row * hidden;

    float local_sum = 0.0f;
    float local_sum_sq = 0.0f;

    for (int i = threadIdx.x; i < hidden; i += blockDim.x) {
        float val = row_in[i];
        local_sum += val;
        local_sum_sq += val * val;
    }

    s_sum[threadIdx.x] = local_sum;
    s_sum_sq[threadIdx.x] = local_sum_sq;
    __syncthreads();

    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + stride];
            s_sum_sq[threadIdx.x] += s_sum_sq[threadIdx.x + stride];
        }
        __syncthreads();
    }

    float mean = s_sum[0] / hidden;
    float variance = (s_sum_sq[0] / hidden) - (mean * mean);
    float inv_std = rsqrtf(variance + eps);

    for (int i = threadIdx.x; i < hidden; i += blockDim.x) {
        float val = row_in[i];
        float normalized = (val - mean) * inv_std;
        row_out[i] = normalized * weight[i] + bias[i];
    }
}

torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(weight.is_cuda() && bias.is_cuda(), "weight and bias must be CUDA tensors");
    TORCH_CHECK(weight.dtype() == torch::kFloat32 && bias.dtype() == torch::kFloat32, "weight and bias must be float32");

    int hidden = x.size(-1);
    TORCH_CHECK(weight.numel() == hidden && bias.numel() == hidden, "weight and bias size must match hidden dimension");

    x = x.contiguous();
    int rows = x.numel() / hidden;

    auto out = torch::empty_like(x);

    int block_size = 256;
    int shared_mem = 2 * block_size * sizeof(float);

    layernorm_kernel<<<rows, block_size, shared_mem>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        rows,
        hidden,
        static_cast<float>(eps)
    );

    return out;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """ an unassuming Transformer block """
    def __init__(self, n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.ln_1 = nn.LayerNorm(n_embd)
        self.attn = CausalSelfAttention(n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen)
        self.ln_2 = nn.LayerNorm(n_embd)
        self.mlp = nn.ModuleDict(dict(
                    c_fc    = nn.Linear(n_embd, 4 * n_embd),
                    c_proj  = nn.Linear(4 * n_embd, n_embd),
                    act     = NewGELU(),
                    dropout = nn.Dropout(resid_pdrop),
                ))
        m = self.mlp
        self.mlpf = lambda x: m.dropout(m.c_proj(m.act(m.c_fc(x))))
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        ext = _stark_get_extension()
        ln1_in = x.contiguous()
        ln1_out = ext.layernorm_forward(ln1_in, self.ln_1.weight, self.ln_1.bias, self.ln_1.eps)
        x = x + self.attn(ln1_out)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        ext = _stark_get_extension()
        ln2_in = x.contiguous()
        ln2_out = ext.layernorm_forward(ln2_in, self.ln_2.weight, self.ln_2.bias, self.ln_2.eps)
        x = x + self.mlpf(ln2_out)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        return x
        # <<<END_IMPROVE>>>

