#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Warp-level reduction helpers
__device__ __forceinline__ float warp_reduce_sum(float val) {
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1)
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}

// Specialized LayerNorm kernel for hidden=768 using float4 vectorization.
// Each block handles one row; 24 warps x 32 threads = 768 threads, each thread
// processes exactly one element. We use a warp-shuffle reduction to compute
// mean/variance, then apply affine in a second pass with float4 stores.
__global__ void layernorm_768_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int rows,
    float eps
) {
    // 768 threads per block, one thread per feature element
    const int HIDDEN = 768;
    const int WARPS = 24; // 768 / 32
    int row = blockIdx.x;
    if (row >= rows) return;

    int tid = threadIdx.x;  // 0..767
    int wid = tid >> 5;     // warp index 0..23
    int lane = tid & 31;    // lane 0..31

    const float* row_in = x + row * HIDDEN;
    float* row_out = out + row * HIDDEN;

    // Each thread loads its element
    float val = row_in[tid];

    // Compute warp-local sums
    float sum = warp_reduce_sum(val);
    float sum_sq = warp_reduce_sum(val * val);

    // Shared memory to accumulate across warps
    __shared__ float s_sum[24];
    __shared__ float s_sum_sq[24];
    if (lane == 0) {
        s_sum[wid] = sum;
        s_sum_sq[wid] = sum_sq;
    }
    __syncthreads();

    // First warp reduces the 24 partial sums
    float total_sum = 0.0f;
    float total_sum_sq = 0.0f;
    if (wid == 0) {
        float ws = (lane < WARPS) ? s_sum[lane] : 0.0f;
        float wss = (lane < WARPS) ? s_sum_sq[lane] : 0.0f;
        // Reduce within first warp (32 lanes, 24 valid)
        #pragma unroll
        for (int offset = 16; offset > 0; offset >>= 1) {
            ws  += __shfl_down_sync(0xffffffff, ws,  offset);
            wss += __shfl_down_sync(0xffffffff, wss, offset);
        }
        if (lane == 0) {
            s_sum[0]    = ws;
            s_sum_sq[0] = wss;
        }
    }
    __syncthreads();

    float mean     = s_sum[0]    / (float)HIDDEN;
    float variance = s_sum_sq[0] / (float)HIDDEN - mean * mean;
    float inv_std  = rsqrtf(variance + eps);

    // Apply affine and write output
    float normalized = (val - mean) * inv_std;
    row_out[tid] = normalized * weight[tid] + bias[tid];
}

// Generic fallback kernel (shared-memory tree reduction, any hidden size)
__global__ void layernorm_generic_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int rows,
    int hidden,
    float eps
) {
