// resid_pdrop=0.0 is assumed; dropout is skipped.
// Uses ATen matmul (cuBLAS) for linear projections.
// ---------------------------------------------------------------------------
torch::Tensor minigpt_ln2_mlp_residual_forward(
    torch::Tensor x,
    torch::Tensor ln_weight, torch::Tensor ln_bias, double ln_eps,
