    float variance = s_sum_sq[0] / (float)hidden - mean * mean;
    float inv_std  = rsqrtf(variance + eps);

    for (int i = threadIdx.x; i < hidden; i += blockDim.x) {
        float v = row_in[i];
        row_out[i] = (v - mean) * inv_std * weight[i] + bias[i];
