    } else {
        int block_size = 256;
        int shared_mem = 2 * block_size * sizeof(float);
        layernorm_generic_kernel<<<rows, block_size, shared_mem>>>(
            x.data_ptr<float>(),
            weight.data_ptr<float>(),
            bias.data_ptr<float>(),
            out.data_ptr<float>(),
            rows, hidden, feps
        );
    }
    return out;
}

